	 public static long maxAlternatingSubstring(int N, String S) {
	        // code here
	        
	        /*
	        
	        6
	           011011
	          22
	        
	        */
	        
	           if(N==1){
	            return 3;
	        }
	        //count alrenative and put in array 
		     int prev=S.charAt(0);
		     int curr=0;
		     int arr[]=new int[N];
		     int ind=0;
		     int val=1; int diff=-1;
		     for(int i=1;i<N;i++){
		         
		         curr=S.charAt(i);
		         if(curr==prev){
		             arr[ind]=val;
		             val=1;
		             ind++;
		         }
		         else{
		             val++;
		             
		         }
		        if(i!=N-1){ 
		         prev=curr;
		        }
		     }
		    
		    //last value 
		      arr[ind]=val;
		     
		  
		  // Complete array 
		  System.out.println(Arrays.toString(arr));
		  
		
		 long Val=0;long ans=0;long resu=0;
		  
		  //best alternative series 
		  if(arr[0]==N){
		      Val=N+1;
		      System.out.println("Here 0 ||");
		     resu=(Val*(Val+1))/2;
		      return resu;
		  }
		  
		 
		  
		  int last=ind+1;int res[]=new int [last];long total=0;
		  for(int i=0;i<last;i++){
		      
		     res[i]=(arr[i]*(arr[i]+1))/2;
		     total=total+res[i];
		  }
		  ans=total;
		 
		 // for 0 
		 Val=((arr[0]+1)*(arr[0]+2))/2;
		 resu=total-res[0]+Val;
		 ans=Math.max(ans,resu);
		 
		 
		 // for N-1
		 Val=((arr[ind]+1)*(arr[ind]+2))/2;
		 resu=total-res[ind]+Val;
		 ans=Math.max(ans,resu);
		 
		 
		 //for 0 to N-1 
		 int count=0;
		 for(int i=0;i<last-1;i++){
		     count=arr[i+1]+arr[i]+1;
		     Val=(count*(count+1))/2;
		     resu=total-res[i+1]-res[i]+Val;
		     ans=Math.max(ans,resu);
		 }
		 
		  return ans;
		  
		        }
		        

