	    public static int getArrange(String NS,int N){
	        int prev=0,curr=0;
	         int count=0;
	        for(int i=0;i<N;i++){
	            prev=NS.charAt(i);
	            for(int j=i;j<N;j++){
	                  
	              curr=NS.charAt(j);
	          //    System.out.println(prev+" "+curr);
	              if(curr==prev && i!=j){
	                  break;
	              }
	              else{
	                  count=count+1;
	                  prev=curr;
	              }
	            }
	            
	        }
	        
	       return count;
	    }
